package com.edgareldy.springboottutorial.entity.token;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Table;
import java.time.Instant;
import lombok.AllArgsConstructor;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import lombok.experimental.SuperBuilder;

/**
 * JPA entity mapping the {@code password_reset_tokens} table. Generated by
 * {@code PasswordResetTokenService} when a user requests a password reset,
 * emailed to them, and deleted (consumed) once used so the token cannot be
 * replayed.
 * <p>
 * Created edgar.muhamyangabo on 10/30/26
 * Author : edgar.muhamyangabo
 * Date : 10/30/26
 * Project : spring-boot-tutorial
 */
@Entity
@Table(name = "password_reset_tokens")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@SuperBuilder
@EqualsAndHashCode(callSuper = true)
public class PasswordResetToken extends AuditableToken {

    @Column(name = "type", nullable = false)
    private String type;

    @Column(name = "expiry_date", nullable = false)
    private Instant expiryDate;
}
